import Foundation

/// Maps an accent colour to one of the precompiled alternate app icons.
/// iOS only switches between icons compiled into the app, so the continuous
/// accent picker is quantised into hue buckets generated by
/// scripts/generate-tinted-icons.py. Keep `step` and names in sync with it.
enum AppIconVariant {
    /// Hue of the primary icon's top-left gradient colour (#2EE0C4).
    static let referenceHue = 170.5
    static let step = 30
    static let monoName = "AppIcon-Mono"
    /// Accents below this saturation (greys, black, white) have no hue to match.
    static let minimumSaturation = 0.15

    static var allNames: [String] {
        stride(from: step, to: 360, by: step).map(name(forRotation:)) + [monoName]
    }

    static func name(forRotation degrees: Int) -> String {
        String(format: "AppIcon-Hue%03d", degrees)
    }

    /// Alternate icon name for an accent, or `nil` for the primary icon.
    /// `nil` RGB means the built-in SideKick Teal, which the primary icon already matches.
    static func iconName(red: Double, green: Double, blue: Double) -> String? {
        let (hue, saturation) = hueAndSaturation(red: red, green: green, blue: blue)
        guard saturation >= minimumSaturation else { return monoName }
        let rotation = (hue - referenceHue).truncatingRemainder(dividingBy: 360)
        let positive = rotation < 0 ? rotation + 360 : rotation
        let bucket = Int((positive / Double(step)).rounded()) % (360 / step)
        return bucket == 0 ? nil : name(forRotation: bucket * step)
    }

    /// Degrees the icon is rotated for a variant, for in-app previews.
    static func rotation(for iconName: String?) -> Double? {
        guard let iconName else { return 0 }
        guard iconName != monoName, iconName.hasPrefix("AppIcon-Hue"),
              let degrees = Int(iconName.dropFirst("AppIcon-Hue".count)) else { return nil }
        return Double(degrees)
    }

    static func hueAndSaturation(red: Double, green: Double, blue: Double) -> (hue: Double, saturation: Double) {
        let maximum = max(red, green, blue)
        let minimum = min(red, green, blue)
        let delta = maximum - minimum
        guard maximum > 0, delta > 0 else { return (0, 0) }
        var hue: Double
        if maximum == red { hue = (green - blue) / delta }
        else if maximum == green { hue = 2 + (blue - red) / delta }
        else { hue = 4 + (red - green) / delta }
        hue *= 60
        if hue < 0 { hue += 360 }
        return (hue, delta / maximum)
    }
}
